def transform(grid):
    h = len(grid)
    out = []
    for i in range(3 * h):
        if i < h:
            row = grid[h - 1 - i]
        elif i < 2 * h:
            row = grid[i - h]
        else:
            row = grid[3 * h - 1 - i]
        out.append(list(reversed(row)) + list(row))
    return out
